<!-- SPDX-License-Identifier: MPL-2.0 -->
<template>
  <div class="account-panel">
    <q-list bordered separator>
      <q-item v-for="account in accounts" :key="account.internalId || account.id" clickable :active="selected===accountRef(account)" active-class="account-active" @click="select(account)">
        <q-item-section avatar><q-avatar color="primary" text-color="white"><span v-if="account.profile?.skin?.url" class="account-face" :style="skinFaceStyle(account.profile.skin.url)" aria-hidden="true"></span><span v-else>{{ (account.profileName||account.displayName||'?').slice(0,1).toUpperCase() }}</span></q-avatar></q-item-section>
        <q-item-section><q-item-label>{{ account.profileName || account.displayName || '未命名账户' }} <q-badge v-if="account.default" color="positive">默认</q-badge><q-badge v-if="account.cacheAvailable" color="info">已缓存</q-badge><q-badge v-else-if="account.cacheState==='not-cached'" color="grey">未缓存</q-badge></q-item-label><q-item-label caption>{{ accountTypeLabel(account) }} · {{ accountStateLabel(account) }} · 缓存：{{ cacheStateLabel(account) }}</q-item-label></q-item-section>
        <q-item-section side><div class="row q-gutter-xs"><q-btn flat label="上移" :disable="busy" @click.stop="move(account,-1)"/><q-btn flat label="下移" :disable="busy" @click.stop="move(account,1)"/><q-btn flat label="默认" :disable="busy" @click.stop="execute('account.set-default',{account:accountRef(account)})"/><q-btn flat color="negative" label="移除" :disable="busy" @click.stop="remove(account)"/></div></q-item-section>
      </q-item>
    </q-list>
    <div v-if="profile" class="q-mt-lg">
      <q-card class="profile-card"><q-card-section><div class="text-h6">{{ profile.name }}</div><div class="text-caption text-grey-5">{{ profile.state }} · {{ profile.canPlayMinecraft ? '可以启动 Minecraft' : '无法启动 Minecraft' }}</div></q-card-section>
        <q-card-section><div class="row q-col-gutter-lg"><div class="col-12 col-md-5"><q-img v-if="profile.skin?.url" :src="profile.skin.url" ratio="1" fit="contain" class="skin-preview"/><div v-else class="skin-empty">没有已装备皮肤</div><div class="row q-gutter-sm q-mt-md"><q-input class="col" dark outlined v-model="skinPath" label="皮肤 PNG 路径"/><q-btn label="导入" :disable="busy || !skinPath" @click="installSkin"/></div><div class="row q-gutter-sm q-mt-sm"><q-select class="col" dark outlined v-model="skinName" :options="skinNames" label="选择本地皮肤"/><q-select class="col" dark outlined v-model="variant" :options="['classic','slim']" label="模型"/><q-btn label="上传并装备" :disable="busy || !skinName" @click="uploadSkin"/></div><q-btn flat color="negative" label="重置远程皮肤" :disable="busy" class="q-mt-sm" @click="resetSkin"/></div>
          <div class="col-12 col-md-7"><div class="text-subtitle1">披风</div><q-list bordered separator class="q-mt-sm"><q-item v-for="cape in profile.capes||[]" :key="cape.id" clickable @click="selectCape(cape)"><q-item-section>{{ cape.alias || cape.id }}</q-item-section><q-item-section side><q-icon :name="cape.current?'check_circle':'radio_button_unchecked'" :color="cape.current?'positive':'grey'"/></q-item-section></q-item></q-list><q-btn flat label="移除披风" :disable="busy" class="q-mt-sm" @click="chooseCape('')"/><div class="text-subtitle1 q-mt-lg">本地皮肤库</div><q-list bordered separator><q-item v-for="skin in skins" :key="skin.name || skin.path"><q-item-section>{{ skin.name || skin.path }}</q-item-section><q-item-section side><q-btn flat color="negative" label="删除" :disable="busy" @click="deleteSkin(skin)"/></q-item-section></q-item></q-list></div></div></q-card-section>
      </q-card>
      <q-card v-if="selectedAccount" class="config-card q-mt-md"><q-card-section><div class="text-subtitle1">认证配置</div><div class="text-caption text-grey-5">可修改认证地址和服务参数，密码不会通过此接口回显。</div></q-card-section><q-card-section v-if="selectedAccount.type==='yggdrasil'"><div class="row q-col-gutter-sm"><q-input class="col-12 col-md-6" dark outlined v-model="config.authUrl" label="认证 URL"/><q-input class="col-12 col-md-6" dark outlined v-model="config.sessionUrl" label="会话 URL"/><q-input class="col-12 col-md-6" dark outlined v-model="config.sourceName" label="服务名称"/><q-select class="col-12 col-md-6" dark outlined v-model="config.tokenType" :options="['Standard','OAuth']" label="令牌类型"/><q-input class="col-12 col-md-6" dark outlined v-model="config.authenticateEndpoint" label="Authenticate endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.refreshEndpoint" label="Refresh endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.validateEndpoint" label="Validate endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.profileEndpoint" label="Profile endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.oauthTokenEndpoint" label="OAuth token endpoint"/></div><q-btn color="primary" class="q-mt-md" :disable="busy" label="保存认证配置" @click="saveConfig"/></q-card-section><q-card-section v-else-if="selectedAccount.type==='unified-pass'"><div class="row q-col-gutter-sm"><q-input class="col-12 col-md-6" dark outlined v-model="config.serverId" label="UnifiedPass Server ID"/><q-input class="col-12 col-md-6" dark outlined v-model="config.baseUrl" label="API Base URL"/></div><q-btn color="primary" class="q-mt-md" :disable="busy" label="保存认证配置" @click="saveConfig"/></q-card-section></q-card>
    </div>
    <q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner>
  </div>
</template>
<script setup lang="ts">
import { ref } from 'vue';
const props=defineProps<{accounts:any[];busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();
const emit=defineEmits<{changed:[]}>();
const selected=ref(''),selectedAccount=ref<any>(null),profile=ref<any>(null),skins=ref<any[]>([]),skinPath=ref(''),skinName=ref(''),variant=ref('classic'),error=ref('');
const config=ref<any>({authUrl:'',sessionUrl:'',sourceName:'',tokenType:'Standard',authenticateEndpoint:'',refreshEndpoint:'',validateEndpoint:'',profileEndpoint:'',oauthTokenEndpoint:'',serverId:'',baseUrl:''});
const skinNames=ref<any[]>([]);
function accountRef(account:any){return String(account?.internalId || account?.id || account?.profileName || '');}
function accountTypeLabel(account:any){const type=String(account?.type||'').toLowerCase();if(type.includes('msa')||type.includes('microsoft'))return 'Microsoft 账户';if(type.includes('ygg')){const server=account?.yggdrasil?.displayName||account?.yggdrasil?.sourceName||account?.authServer?.displayName||account?.authServerName||'第三方认证';return `第三方认证 · ${server}`;}if(type.includes('unified')){const server=account?.unifiedPass?.displayName||account?.unifiedPass?.serverName||account?.unifiedPass?.serverId||account?.authServer?.displayName||account?.authServerName||'UnifiedPass';return `UnifiedPass · ${server}`;}return '离线账户';}
function accountStateLabel(account:any){const state=String(account?.stateName||'').toLowerCase();return ({online:'在线',working:'登录中',offline:'离线',expired:'已过期',errored:'错误',disabled:'已禁用',gone:'已失效',unchecked:'未检查'} as any)[state] || (account?.stateName || '未检查');}
function cacheStateLabel(account:any){const state=String(account?.cacheState||'unknown');return ({cached:'已缓存','not-cached':'未缓存',unknown:'检查中'} as any)[state] || '未知';}
function skinFaceStyle(url:string){return {backgroundImage:`url("${String(url).replace(/"/g,'%22')}")`};}
async function attempt(action:()=>Promise<any>){error.value='';try{return await action();}catch(e){error.value=String(e);}}
async function select(account:any){const reference=accountRef(account);selected.value=reference;selectedAccount.value=account;config.value={authUrl:account.yggdrasil?.authUrl||'',sessionUrl:account.yggdrasil?.sessionUrl||'',sourceName:account.yggdrasil?.sourceName||'',tokenType:account.yggdrasil?.tokenType||'Standard',authenticateEndpoint:account.yggdrasil?.authenticateEndpoint||'',refreshEndpoint:account.yggdrasil?.refreshEndpoint||'',validateEndpoint:account.yggdrasil?.validateEndpoint||'',profileEndpoint:account.yggdrasil?.profileEndpoint||'',oauthTokenEndpoint:account.yggdrasil?.oauthTokenEndpoint||'',serverId:account.unifiedPass?.serverId||'',baseUrl:account.unifiedPass?.baseUrl||''};await attempt(async()=>{profile.value=await props.execute('account.profile',{account:reference});skins.value=await props.execute('account.skin.list',{account:reference});skinNames.value=skins.value.map((s:any)=>s.name||s.path);});}
async function move(a:any,delta:number){await attempt(async()=>{await props.execute('account.move',{account:accountRef(a),delta});emit('changed');});}
async function remove(a:any){await attempt(async()=>{await props.execute('account.remove',{account:accountRef(a),confirm:true});profile.value=null;selected.value='';emit('changed');});}
async function installSkin(){await attempt(async()=>{await props.execute('account.skin.install',{account:selected.value,path:skinPath.value});skinPath.value='';await select({id:selected.value});});}
async function uploadSkin(){await attempt(async()=>{await props.execute('account.skin.upload',{account:selected.value,skin:skinName.value,variant:variant.value});await select({id:selected.value});});}
async function resetSkin(){await attempt(async()=>{await props.execute('account.skin.reset',{account:selected.value,confirm:true});await select({id:selected.value});});}
async function deleteSkin(s:any){await attempt(async()=>{await props.execute('account.skin.delete',{account:selected.value,skin:s.name||s.path,confirm:true});await select({id:selected.value});});}
async function chooseCape(cape:string){await attempt(async()=>{await props.execute('account.cape.select',{account:selected.value,cape});await select({id:selected.value});});}
function selectCape(cape:any){return chooseCape(cape.id);}
async function saveConfig(){await attempt(async()=>{const p:any={account:selected.value};if(selectedAccount.value?.type==='yggdrasil')Object.assign(p,{authUrl:config.value.authUrl,sessionUrl:config.value.sessionUrl,sourceName:config.value.sourceName,tokenType:config.value.tokenType,authenticateEndpoint:config.value.authenticateEndpoint,refreshEndpoint:config.value.refreshEndpoint,validateEndpoint:config.value.validateEndpoint,profileEndpoint:config.value.profileEndpoint,oauthTokenEndpoint:config.value.oauthTokenEndpoint});else Object.assign(p,{serverId:config.value.serverId,baseUrl:config.value.baseUrl});await props.execute('account.configure',p);emit('changed');});}
</script>
<style scoped>.account-panel{max-width:1100px}.account-face{display:block;width:100%;height:100%;border-radius:inherit;background-repeat:no-repeat;background-size:800% 800%;background-position:14.2857% 14.2857%;image-rendering:pixelated;image-rendering:crisp-edges}.skin-preview :deep(img){image-rendering:pixelated;image-rendering:crisp-edges}.profile-card{background:var(--neo-panel);border:1px solid var(--neo-border)}.skin-preview{max-width:320px;background:#101827;border-radius:14px}.skin-empty{height:260px;display:grid;place-items:center;background:#101827;border-radius:14px;color:var(--neo-muted)}.account-active{background:rgba(99,102,241,.18)}</style>
